parts=['''<!doctype html><html lang="en-AU"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stratus 1.6.12 water checks</title><style>body{margin:0;background:#111923;color:#e8f1fa;font:16px/1.5 system-ui}main{max-width:1200px;margin:auto;padding:24px}a{color:#9ed6ff}figure{margin:0 0 24px;background:#1d2c3c;border-radius:10px;overflow:hidden}img{display:block;width:100%;height:auto}figcaption{padding:12px}small{display:block;color:#b9cbdc}.note{padding:16px;background:#24394d;border-radius:8px;margin:20px 0}button{font:inherit;border:1px solid #8ac9ef;border-radius:6px;padding:8px 14px;background:#19354a;color:#fff;cursor:pointer;margin:0 8px 12px 0}button[aria-pressed=true]{background:#46748c}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:20px}h1{margin-bottom:8px}</style><main><h1>Stratus 1.6.12</h1><p>Vanilla water tint across the whole visible surface, including distant reflections.</p><div class="note">Actual Minecraft Main captures at 1440 × 842. All62 controls and approved quality settings preserved. FPS remains deferred; these are visual checks, not performance evidence. A pre-existing rectangular tint band just below the water surface remains unresolved: matched1.6.11 and1.6.12 views are labelled below, and waterline acceptance stays pending. Texture, ripples and clouds animate between captures.</div><p><a href="../Stratus-1.6.12.zip">Release ZIP</a> · <a href="../Stratus-1.6.12-install.json">Install/load receipt</a> · <a href="manifest.json">Capture manifest</a></p><h2>Matched close view</h2><button aria-pressed="false" data-state="off">Texture off</button><button aria-pressed="true" data-state="on">Default / maximum</button><figure><img id="comparison" src="captures/s1612-close-on.png" alt="Close river comparison, whole-surface tint enabled"><figcaption id="comparison-label">Whole-surface tint: default / maximum</figcaption></figure><h2>Evidence gallery</h2><div class="grid">''']
for r in rows:
 parts.append('<figure><img loading="lazy" src="'+html.escape(r['file'])+'" alt="'+html.escape(Path(r['file']).stem)+'"><figcaption><strong>'+html.escape(Path(r['file']).stem)+'</strong><p>'+html.escape(r['review'])+'</p><small>'+html.escape(str(r.get('pack')))+'<br>'+html.escape(str(r.get('camera')))+'</small></figcaption></figure>')
parts.append('''</div><script>document.querySelectorAll('[data-state]').forEach(b=>b.addEventListener('click',()=>{const state=b.dataset.state;document.querySelector('#comparison').src='captures/s1612-close-'+state+'.png';document.querySelector('#comparison-label').textContent=state==='on'?'Whole-surface tint: default / maximum':'Added native surface tint disabled';document.querySelectorAll('[data-state]').forEach(x=>x.setAttribute('aria-pressed',x===b));}));</script></main></html>''');(report/'index.html').write_text(''.join(parts));print(len(rows),'captures in report;',len(notes),'review notes recorded.')
